#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 0x800
#define MAX_BUF  0x800

static char main_line[MAX_LINE];
static char main_key[MAX_BUF];
static char main_val[MAX_BUF];

static void decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, j = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dst[j++] = ' ';
            i++;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            char hi = src[i + 1];
            char lo = src[i + 2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' : (toupper((unsigned char)hi) - 'A' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' : (toupper((unsigned char)lo) - 'A' + 10));
            dst[j++] = (char)val;
            i += 3;
        } else {
            dst[j++] = c;
            i++;
        }
    }
    dst[j] = '\0';
}

int main(void)
{
    if (fgets(main_line, sizeof(main_line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }
    size_t len = strlen(main_line);
    while (len > 0 && (main_line[len - 1] == '\n' || main_line[len - 1] == '\r')) {
        main_line[--len] = '\0';
    }
    char *p = main_line;
    while (*p) {
        char *token_start = p;
        char *amp = strchr(p, '&');
        size_t token_len = amp ? (size_t)(amp - p) : strlen(p);
        char *eq = memchr(token_start, '=', token_len);
        if (eq) {
            size_t key_len = (size_t)(eq - token_start);
            size_t val_len = token_len - key_len - 1;
            decode(token_start, key_len, main_key);
            decode(eq + 1, val_len, main_val);
        } else {
            decode(token_start, token_len, main_key);
            main_val[0] = '\0';
        }
        printf("%s=%s\n", main_key, main_val);
        if (!amp) break;
        p = amp + 1;
    }
    return 0;
}
